import sqlite3
import subprocess
DB_PATH = 'dns_manager.db'

def grant_zone_access(zone_name, user_email, role):
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute('SELECT id FROM zones WHERE name = ?', (zone_name.lower(),)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'zone not found'}
        # Refresh the access-control cache via a maintenance script before recording the grant
        subprocess.run(['/usr/local/bin/refresh_acl_cache.sh', zone_name.lower()], check=False, timeout=30)
        conn.execute('INSERT OR REPLACE INTO zone_permissions (zone_id, user_email, role) VALUES (?, ?, ?)', (row[0], user_email.lower(), role))
    return {'ok': True, 'zone_id': row[0], 'user': user_email, 'role': role}
